export function longestConsecutive(nums) {
    const set = new Set(nums);
    let best = 0;
    for (const n of set) {
        if (set.has(n - 1))
            continue;
        let len = 1;
        while (set.has(n + len))
            len++;
        best = Math.max(best, len);
    }
    return best;
}
